let playersUI={query:'',team:'all',position:'all'};
function playerDirectoryRows(){return [...state.teams.flatMap(club=>club.roster.map(p=>({p,club}))),...state.free.map(p=>({p,club:null}))].filter(({p,club})=>(playersUI.team==='all'||playersUI.team===(club?String(club.id):'free'))&&(playersUI.position==='all'||playersUI.position===p.pos)&&p.name.toLowerCase().includes(playersUI.query.toLowerCase().trim())).sort((a,b)=>b.p.ovr-a.p.ovr||a.p.name.localeCompare(b.p.name))}
function updatePlayersFilter(key,value){if(!['query','team','position'].includes(key))return;playersUI[key]=value;document.getElementById('players-directory-results').innerHTML=playersDirectoryTable()}
function viewDirectoryPlayer(id,tab){if(!['Overview','Attributes','Tendencies'].includes(tab)||!playerContext(id))return;activePlayerId=id;playerTab=tab;renderPlayerProfile();const d=document.getElementById('profile');if(!d.open)d.showModal()}
function playersDirectoryTable(){const rows=playerDirectoryRows();return `<p class="note">${rows.length} players · Highest overall first</p><div class="scroll" tabindex="0" role="region" aria-label="Player directory"><table><thead><tr><th>Player</th><th>Team</th><th>POS</th><th>Age</th><th>OVR</th><th>POT</th><th>Player details</th></tr></thead><tbody>${rows.map(({p,club})=>`<tr><th scope="row"><button class="namebutton" onclick="viewDirectoryPlayer(${p.id},'Overview')">${escapeHTML(p.name)}</button><small class="directory-archetype">${escapeHTML(archetypeProfile(p).name)}</small></th><td><span class="directory-team">${club?secondaryTeamLogo(club):''}${escapeHTML(club?club.city+' '+club.name:'Free agent')}</span></td><td>${p.pos}</td><td>${p.age}</td><td>${ratingMarkup(p.ovr)}</td><td>${ratingMarkup(p.pot)}</td><td><div class="directory-details"><button onclick="viewDirectoryPlayer(${p.id},'Attributes')">Attributes</button><button onclick="viewDirectoryPlayer(${p.id},'Overview')">Bio</button><button onclick="viewDirectoryPlayer(${p.id},'Tendencies')">Tendencies</button></div></td></tr>`).join('')||'<tr><td colspan="7">No players match these filters.</td></tr>'}</tbody></table></div>`}
function playersView(){return `<section class="panel"><div class="panelhead"><h2>Players</h2><span class="muted">League rosters & free agents</span></div><div class="directory-filters"><label>Search players<input type="search" value="${escapeHTML(playersUI.query)}" placeholder="Player name" oninput="updatePlayersFilter('query',this.value)"></label><label>Team<select onchange="updatePlayersFilter('team',this.value)">${[['all','All teams & free agents'],['free','Free agents'],...state.teams.map(t=>[String(t.id),t.city+' '+t.name])].map(([v,n])=>`<option value="${v}" ${playersUI.team===v?'selected':''}>${escapeHTML(n)}</option>`).join('')}</select></label><label>Position<select onchange="updatePlayersFilter('position',this.value)">${['all','PG','SG','SF','PF','C'].map(v=>`<option value="${v}" ${playersUI.position===v?'selected':''}>${v==='all'?'All positions':v}</option>`).join('')}</select></label></div><div id="players-directory-results">${playersDirectoryTable()}</div></section>`}
